s=page(68,U,'59','Hard disks: read-write head, actuator; tracks and sectors; Figure 2.11','ہارڈ ڈسکس: ریڈ رائٹ ہیڈ، ایکچویٹر؛ ٹریکس اور سیکٹرز؛ شکل ۲.۱۱','هارډ ډیسکونه: لوستلو-لیکلو سر، حرکتي؛ ټریکونه او سیکټورونه؛ انځور ۲.۱۱','p059')
F=Flow(s)
add(s,'a','Information is written to and read from a platter as it rotates. The read-and-write head is used to detect and modify the magnetization of the material immediately under it. An actuator arm (or access arm) moves the heads on an arc across the platters as they spin, allowing each head to access almost the entire surface of the platter as it spins. A typical HDD has two electric motors; a disk motor that spins the disks and an actuator (motor) that positions the read/write head assembly across the spinning disks.','پلیٹ کے گھومتے وقت اس پر معلومات لکھی اور اس سے پڑھی جاتی ہیں۔ ریڈ اینڈ رائٹ ہیڈ اپنے عین نیچے موجود مادے کی مقناطیسیت کو معلوم کرنے اور تبدیل کرنے کے لیے استعمال ہوتا ہے۔ ایک ایکچویٹر آرم (یا رسائی آرم) ہیڈز کو پلیٹوں کے گھومتے وقت ان پر ایک قوس میں حرکت دیتا ہے جس سے ہر ہیڈ گھومتی ہوئی پلیٹ کی تقریباً پوری سطح تک پہنچ سکتا ہے۔ ایک عام ایچ ڈی ڈی میں دو برقی موٹریں ہوتی ہیں؛ ایک ڈسک موٹر جو ڈسکس کو گھماتی ہے اور ایک ایکچویٹر (موٹر) جو ریڈ / رائٹ ہیڈ اسمبلی کو گھومتی ہوئی ڈسکس پر مقرر کرتا ہے۔','معلومات د پلېټ په ګرځېدو پر هغې لیکل کېږي او له هغې نه لوستل کېږي. د لوستلو-او-لیکلو سر د خپل ژر لاندې موادو د مقناطیسي کېدو کشفولو او بدلولو لپاره کارول کېږي. یو حرکتي بازو (یا د لاسرسي بازو) سرونه د پلېټونو په ګرځېدو پر هغو په یوه قوس خوځوي چې هر سر ته اجازه ورکوي د ګرځېدونکي پلېټ نژدې ټوله سطحې ته لاسرسی ومومي. یو عادي HDD دوه برېښنايي موټرونه لري؛ یو د ډیسک موټر چې ډیسکونه ګرځوي او یو حرکتي (موټر) چې د لوستلو/لیکلو سر مجلس په ګرځېدونکو ډیسکونو ټاکي.')
add(s,'b','The surface of the disk is divided into tracks and sectors before writing data, as shown in Figure 2.11.','ڈیٹا لکھنے سے پہلے ڈسک کی سطح کو ٹریکس اور سیکٹرز میں تقسیم کیا جاتا ہے، جیسا کہ شکل ۲.۱۱ میں دکھایا گیا ہے۔','د ډېټا له لیکلو مخکې د ډیسک سطحه په ټریکونو او سیکټورونو وېشل کېږي، لکه څنګه چې ۲.۱۱ انځور کې ښودل شوي.')
def ts():
    import math
    b='<g fill="none" stroke="#111" stroke-width="1">'
    for r in range(25,95,6): b+=f'<circle cx="130" cy="110" r="{r}"/>'
    for a in range(0,360,40):
        x=130+95*math.cos(math.radians(a)); y=110+95*math.sin(math.radians(a))
        x0=130+25*math.cos(math.radians(a)); y0=110+25*math.sin(math.radians(a))
        b+=f'<line x1="{x0:.1f}" y1="{y0:.1f}" x2="{x:.1f}" y2="{y:.1f}"/>'
    b+='</g><circle cx="130" cy="110" r="22" fill="#fff" stroke="#111"/>'
    b+=T(235,48,'tracks',15,'start',700)+'<line x1="222" y1="50" x2="150" y2="36" stroke="#111"/>'
    b+=T(240,90,'One Sector',15,'start',700)+'<line x1="238" y1="86" x2="185" y2="95" stroke="#111"/>'
    b+='<path d="M60 250 Q160 190 300 215 L300 270 Q170 245 70 305 Z" fill="#fff" stroke="#111" stroke-width="1.5"/>'
    for i,f in enumerate(['#fff','#554a99','#fff','#fff','#554a99','#554a99','#fff','#554a99']):
        b+=f'<rect x="{80+i*26}" y="{248-i*3 if i<4 else 232+(i-4)*0}" width="16" height="16" fill="{f}" stroke="#111"/>'
    b+=T(330,208,'tracks',15,'start',700)
    return svg(430,330,'Tracks and sectors on a hard disk platter',b)
s['figures']=[dict(id='cs11-s068-fig1',svg=ts(),caption='Figure 2.11 Tracks and Sectors in Hard disk',captionUrdu='شکل ۲.۱۱ ہارڈ ڈسک میں ٹریکس اور سیکٹرز',captionPashto='انځور ۲.۱۱ په هارډ ډیسک کې ټریکونه او سیکټورونه',labels=[lab('tracks','ٹریکس','ټریکونه'),lab('One Sector','ایک سیکٹر','یو سیکټور')])]
F.fg(0)
add(s,'c','Tracks are concentric circles (circles within circles). The data bits are recorded as tiny magnetic spots on the tracks.','ٹریکس ہم مرکز دائرے ہیں (دائروں کے اندر دائرے)۔ ڈیٹا بٹس ٹریکس پر چھوٹے مقناطیسی دھبوں کی صورت میں ریکارڈ ہوتے ہیں۔','ټریکونه ګډ مرکزي کړۍ دي (په کړیو کې کړۍ). د ډېټا بټونه په ټریکونو پر وړو مقناطیسي نقطو ثبتېږي.')
add(s,'d','Sectors are the further divisions of tracks, which hold a block of data that is read or written at one time. Modern disks have more sectors in the outer tracks','سیکٹرز ٹریکس کی مزید تقسیم ہیں جو ڈیٹا کا ایک بلاک رکھتے ہیں جو ایک وقت میں پڑھا یا لکھا جاتا ہے۔ جدید ڈسکس کے بیرونی ٹریکس میں زیادہ سیکٹرز ہوتے ہیں','سیکټورونه د ټریکونو نور وېشنې دي چې د ډېټا یو بلاک لري چې په یو وخت لوستل یا لیکل کېږي. مدرن ډیسکونه په بهرنیو ټریکونو کې ډیر سیکټورونه لري',cont=True)
F.done()
